-- Pure RAW page validation: does not authorize, reserve, retain or normalize.
CREATE FUNCTION population_top3000_202608_202609_v1.raw_minute_page_validate_v3(p_manifest_text text,p_content_text text,p_expected_stored_sha text) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='pg_catalog' AS $fn$
DECLARE context jsonb;m jsonb;b jsonb;rows jsonb;count_rows bigint;next_url text;path text;present text;
BEGIN
context:=population_top3000_202608_202609_v1.raw_minute_manifest_validate_v1(p_manifest_text);m:=context->'manifest';
IF p_content_text IS NULL OR octet_length(p_content_text) NOT BETWEEN 1 AND (m->>'max_response_bytes')::bigint OR p_expected_stored_sha IS NULL OR encode(sha256(convert_to(p_content_text,'UTF8')),'hex') IS DISTINCT FROM p_expected_stored_sha THEN RAISE EXCEPTION 'RAW_PAGE_EXACT_BYTES_HASH_REQUIRED';END IF;
BEGIN b:=p_content_text::jsonb;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'RAW_PAGE_JSON_INVALID';END;
IF jsonb_typeof(b) IS DISTINCT FROM 'object' OR b->>'ticker' IS DISTINCT FROM m->>'symbol' OR b->>'status' IS DISTINCT FROM 'OK' OR b->'adjusted' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'RAW_PAGE_ENVELOPE';END IF;
-- Traverse original json, not jsonb, so duplicate keys cannot silently collapse.
IF EXISTS(WITH RECURSIVE nodes(j) AS(
 SELECT p_content_text::json UNION ALL
 SELECT child.value FROM nodes n CROSS JOIN LATERAL(
  SELECT value FROM json_each(CASE WHEN json_typeof(n.j)='object' THEN n.j ELSE '{}'::json END)
  UNION ALL SELECT value FROM json_array_elements(CASE WHEN json_typeof(n.j)='array' THEN n.j ELSE '[]'::json END)
 )child
) SELECT 1 FROM nodes n WHERE json_typeof(n.j)='object' AND EXISTS(SELECT key FROM json_each(n.j) GROUP BY key HAVING count(*)>1)) THEN RAISE EXCEPTION 'RAW_PAGE_DUPLICATE_JSON_KEY';END IF;
IF b?'results' THEN
 IF jsonb_typeof(b->'results') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'RAW_PAGE_RESULTS';END IF;rows:=b->'results';present:='ARRAY';
ELSIF b->'resultsCount'='0'::jsonb THEN rows:='[]';present:='OMITTED_WITH_EXPLICIT_ZERO';
ELSE RAISE EXCEPTION 'RAW_PAGE_RESULTS';END IF;
count_rows:=jsonb_array_length(rows);
IF count_rows>50000 OR EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE jsonb_typeof(r) IS DISTINCT FROM 'object') OR EXISTS(SELECT 1 FROM unnest(ARRAY['queryCount','resultsCount']) k WHERE b?k AND (jsonb_typeof(b->k) IS DISTINCT FROM 'number' OR coalesce(b->>k,'')!~'^[0-9]+$')) OR (b?'resultsCount' AND (b->>'resultsCount')::numeric<>count_rows) THEN RAISE EXCEPTION 'RAW_PAGE_COUNTS';END IF;
next_url:=nullif(b->>'next_url','');path:=split_part(context->>'first_url','?',1)||'?cursor=';
IF next_url IS NOT NULL AND (jsonb_typeof(b->'next_url') IS DISTINCT FROM 'string' OR left(next_url,length(path))<>path OR substring(next_url FROM length(path)+1)!~'^[A-Za-z0-9_.~%+-]+$' OR length(next_url)>16384 OR substring(next_url FROM length(path)+1) ~ '%([^0-9A-F]|[0-9A-F]([^0-9A-F]|$)|$)' OR next_url ~ '[[:cntrl:][:space:]]') THEN RAISE EXCEPTION 'RAW_PAGE_SANITIZED_CURSOR_REQUIRED';END IF;
IF p_content_text ~* '"(apiKey|api_key|access_token|authorization)"[[:space:]]*:' OR p_content_text ~* '[?&](apiKey|api_key|access_token)=' THEN RAISE EXCEPTION 'RAW_PAGE_CREDENTIAL_ECHO';END IF;
RETURN jsonb_build_object('request_sha256',m->>'request_sha256','stored_sha256',p_expected_stored_sha,'stored_bytes',octet_length(p_content_text),'result_count',count_rows,'results_presence',present,'next_url',next_url,'terminal',next_url IS NULL,'source_accepted',false,'normalized_values_created',0,'no_trade_inferred',false,'original_historical_receipt_at',NULL);
END $fn$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.raw_minute_page_validate_v3(text,text,text) FROM PUBLIC,anon,authenticated;

